slides.code:
function greet(name) {   // name — PARAMETER
  return "Hello, " + name;
}
greet("Anya");           // "Anya" — ARGUMENT

function introduce(name, age) {
  return `My name is ${name}, I'm ${age}`;
}
console.log(introduce("Aziz", 16));
// My name is Aziz, I'm 16

function greetNoReturn(name) {
  "Hello, " + name; // no return
}
console.log(greetNoReturn("Anya")); // undefined

// 1. regular
function greet(name) {
  return "Hello, " + name;
}

// 2. arrow
const greet = (name) => {
  return "Hello, " + name;
};

// 3. arrow, short
const greet = name => "Hello, " + name;

slides.text:
How to shorten it:
one parameter — you can drop the parentheses around it;
only return inside — drop the `{ }` and the word `return`;
two or more parameters — the parentheses stay: `(a, b) => a + b`.

slides.code:
function welcome(name) {
  return `Hello, ${name}! Welcome to the lesson.`;
}
console.log(welcome("Aziz"));
console.log(welcome("Ali"));

const names = ["Aziz", "Ali", "Malika"];
for (const name of names) {
  console.log(welcome(name));
}

function sum(a, b) {
  return a + b;
}
console.log(sum(2, 3));  // 5
console.log(sum(-5, 5)); // 0

// as an arrow function:
const sum = (a, b) => a + b;

